import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type DiaWordCarouselProps = Record<string, any>;

const DiaWordCarousel: React.FC<DiaWordCarouselProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  primaryColor = "#ffffff",
  accentColor = "#00d4ff",
  words = "Design, Develop, Deploy, Scale",
  fontSize = 100,
  durationInSeconds = 10,
  durationPerWord = 2.5,
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Parse words
  const wordArray = React.useMemo(() => {
    return words.split(",").map((w) => w.trim()).filter((w) => w.length > 0);
  }, [words]);

  // Timing Logic
  const framesPerWord = fps * durationPerWord;
  const wordIndex = Math.floor(frame / framesPerWord) % wordArray.length;
  const currentWord = wordArray[wordIndex];
  
  // Local timing within the word's lifespan
  const localFrame = frame % framesPerWord;
  
  // 1. Entrance Animation (Slide Up + Fade In)
  const entranceDuration = 25;
  const entranceOpacity = interpolate(localFrame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });
  
  const entranceOffset = spring({
    frame: localFrame,
    fps,
    config: { damping: 12, stiffness: 100 },
    from: 40,
    to: 0,
  });

  // 2. Gradient Sweep Effect (Occurs in the middle)
  const sweepStart = 25;
  const sweepDuration = framesPerWord - 50; // Ensure it finishes before exit
  const safeSweepDuration = Math.max(sweepDuration, 10); // Prevent negative ranges
  
  const sweepProgress = interpolate(
    localFrame,
    [sweepStart, sweepStart + safeSweepDuration],
    [0, 200], // Moves background position from 0% to 200%
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 3. Exit Animation (Slide Up + Fade Out)
  const exitStart = framesPerWord - 20;
  const exitOpacity = interpolate(
    localFrame,
    [exitStart, framesPerWord],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const exitOffset = interpolate(
    localFrame,
    [exitStart, framesPerWord],
    [0, -40],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Combine transformations
  // While entering: offset is positive (coming from bottom)
  // While exiting: offset becomes negative (going to top)
  // The transition between entranceOffset (settles at 0) and exitOffset (starts at 0) needs careful handling.
  // Since entranceOffset is a spring that settles at 0, and exitOffset starts at 0, we can sum them 
  // BUT interpolate logic for exitOffset ensures it is 0 until exitStart.
  
  const currentTranslateY = localFrame < exitStart ? entranceOffset : exitOffset;
  const currentOpacity = localFrame < exitStart ? entranceOpacity : exitOpacity;
  const currentScale = interpolate(localFrame, [0, framesPerWord], [0.95, 1.05], { extrapolateRight: "clamp" });

  // Styling
  const bgColor = transparentBackground ? "#00000000" : backgroundColor;

  // Gradient Text Logic
  // We create a gradient that is mostly primaryColor, with a sliver of accentColor passing through
  // Gradient structure: Primary (0-40%) -> Accent (50%) -> Primary (60-100%)
  // We animate the background size/position to make it "sweep"
  const gradientStyle: React.CSSProperties = {
    fontFamily: "Montserrat",
    fontSize: fontSize,
    fontWeight: 800,
    textAlign: "center",
    lineHeight: 1.2,
    
    // The Magic Gradient
    backgroundImage: `linear-gradient(
      120deg, 
      ${primaryColor} 0%, 
      ${primaryColor} 40%, 
      ${accentColor} 50%, 
      ${primaryColor} 60%, 
      ${primaryColor} 100%
    )`,
    backgroundSize: "250% 100%", // Large enough to hide the accent stripe off-screen initially
    backgroundPosition: `${100 - (sweepProgress / 2)}% 0%`, // Move across
    backgroundClip: "text",
    WebkitBackgroundClip: "text",
    color: "transparent", // Crucial for gradient text
    
    // Animation props
    opacity: currentOpacity,
    transform: `translateY(${currentTranslateY}px) scale(${currentScale})`,
    width: width * 0.9, // Responsive width
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      <div style={gradientStyle}>
        {currentWord}
      </div>
    </AbsoluteFill>
  );
};

export default DiaWordCarousel;